export function addExpandedDemos(scenarios) {
  for (const [language, copy] of Object.entries(messages)) {
    for (const [index, key] of ['morning', 'medicine', 'home_safety', 'voice'].entries()) {
      const [parentMsg, ...labels] = copy[key];
      scenarios[key].label[language] = copy.labels[index];
      scenarios[key][language] = {
        parentMsg, time: scenarios[key].en.time,
        buttons: labels.map((label, i) => {
          const kind = (key === 'voice' && i === 1) || (['morning', 'home_safety'].includes(key) && i === 2) ? 'alert' : key === 'voice' ? 'voice' : 'reply';
          const replyText = key === 'voice' ? i === 0 ? copy.voiceReply : copy.alertReply : label;
          return { label, replyText, kind, mood: kind === 'alert' ? '🚨' : kind === 'voice' ? '🎤' : '💬',
            feedText: (kind === 'alert' ? copy.alertUpdate : kind === 'voice' ? copy.voiceUpdate : copy.update) + replyText };
        }),
      };
    }
  }
  return scenarios;
}
